const fs = await import('node:fs/promises');
const S = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts";
const P2 = "D:\\GitHub\\My-second-brain\\50-知识\\AI工具";
const master = JSON.parse(await fs.readFile(S+"\\_GIG_MASTER.json","utf8"));

// 每日巡检表：按「活的更新频率」排序
const ROUTINE = [
  { freq:"每天", note:"活更新快，值得天天看", hosts:["freelancer.com","upwork.com","peopleperhour.com","toptal.com","fiverr.com","dribbble.com","prolific.com","userfeel.com","userlytics.com","validately.com","usabilityhub.com","userzoom.com","testingtime.com","playtestcloud.com","clickworker.com","oneforma.com","figure-eight.com","microworkers.com","toloka.ai","remotasks.com"] },
  { freq:"每周", note:"活更新慢，每周看2-3次", hosts:["scribie.com","castingwords.com","gotranscript.com","rev.com","transcribeme.com","transcriptionhub.com","smartcat.com","unbabel.com","onehourtranslation.com","textroyal.com","writeraccess.com","crowdcontent.com","scripted.com","ndash.com","iwriter.com","constant-content.com","textbroker.com","zbj.com","proginn.com","shixian.com","yuanjisong.com","tezign.com"] },
  { freq:"每周看1次", note:"要审核/竞争大，看到合适的再投", hosts:["varsitytutors.com","studypool.com","cambly.com","preply.com","wyzant.com","tutorhunt.com","hackenproof.com","synack.com","cobalt.io","bugbase.in","mercor.com","alignerr.com","outlier.ai","dataannotation.tech","appen.com","scale.com","mturk.com","glg.com","thirdbridge.com","tegus.com","zintro.com","ttec.com","arise.com","concentrix.com","workingnotworking.com","99designs.com","designcrowd.com","streetbees.com","premise.com","prizerebel.com","guru.com","truelancer.com","freelancehunt.com"] }
];

const lookup = {};
for (const [cat, items] of Object.entries(master.groups)) for (const it of items) lookup[it.host.toLowerCase()] = { ...it, cat };

const rows=[];
const add=s=>rows.push(s);
add("---"); add("date: 2026-10-21"); add("tags: [工作, 搞钱, 接单平台, 巡检表, 每天用]"); add("---"); add("");
add("# 接单平台每日巡检表（70 个，按频率分）");
add("");
add("> **这份表的用途：你每天照着扫一遍，扫完打勾。**");
add("> **核心逻辑：不是所有平台都要天天看，按「活更新速度」分三档。**");
add("");
add("## 一、⭐⭐ 怎么用");
add("");
add("| 时间 | 做什么 |");
add("|---|---|");
add("| **早上 15 分钟** | 扫「每天」那 20 个，看有没有新活 |");
add("| **周一/周四** | 扫「每周」那 22 个 |");
add("| **周末** | 扫「每周看1次」那 33 个（这类竞争大，挑着投） |");
add("| **有活** | 立刻投，不管钱多少先做一单 |");
add("");
add("**别贪多：一天 15 分钟足够了。扫完该干嘛干嘛。**");
add("");
add("## 二、⭐⭐ 每天必看（20 个）——活更新最快");
add("");
add("| ☐ | 平台 | 类型 | 级别 | 网址 |");
add("|---|---|---|---|---|");
for (const h of ROUTINE[0].hosts) {
  const it = lookup[h.toLowerCase()];
  if (!it) continue;
  add("| ☐ | **"+it.name+"** | "+(it.cat||"").replace(/[🌍🧪🎓💰📝✍️🌐🤖💼📍🎨🇨🇳]/g,'').trim()+" | "+(it.group==="能看到活"?"A":"B")+" | "+it.host+" |");
}
add("");
add("**这 20 个里，前 5 个（Freelancer/Upwork/Prolific/Clickworker/Userfeel）看完就够本了。**");
add("");
add("## 三、⭐ 每周看 2-3 次（22 个）——活更新较慢");
add("");
add("| ☐ | 平台 | 类型 | 级别 | 网址 |");
add("|---|---|---|---|---|");
for (const h of ROUTINE[1].hosts) {
  const it = lookup[h.toLowerCase()];
  if (!it) continue;
  add("| ☐ | **"+it.name+"** | "+(it.cat||"").replace(/[🌍🧪🎓💰📝✍️🌐🤖💼📍🎨🇨🇳]/g,'').trim()+" | "+(it.group==="能看到活"?"A":"B")+" | "+it.host+" |");
}
add("");
add("## 四、每周看 1 次（33 个）——要审核或竞争大");
add("");
add("| ☐ | 平台 | 类型 | 级别 | 网址 |");
add("|---|---|---|---|---|");
for (const h of ROUTINE[2].hosts) {
  const it = lookup[h.toLowerCase()];
  if (!it) continue;
  add("| ☐ | "+it.name+" | "+(it.cat||"").replace(/[🌍🧪🎓💰📝✍️🌐🤖💼📍🎨🇨🇳]/g,'').trim()+" | "+(it.group==="能看到活"?"A":"B")+" | "+it.host+" |");
}
add("");
add("## 五、⭐⭐ 记录表（每接一单记一行）");
add("");
add("| 日期 | 平台 | 什么活 | 报价 | 状态 | 到账 |");
add("|---|---|---|---|---|---|");
add("| | | | | | |");
add("| | | | | | |");
add("| | | | | | |");
add("| | | | | | |");
add("| | | | | | |");
add("");
add("**这张表比什么都重要——做 10 单之后你就能看出哪个平台值得留。**");
add("");
add("## 六、⭐ 前两周的目标");
add("");
add("| 周 | 目标 | 判断标准 |");
add("|---|---|---|");
add("| 第 1 周 | 注册完「每天」那 20 个 | 20 个都有账号 |");
add("| 第 1 周 | 至少投/接 3 单 | 不管钱多少 |");
add("| 第 2 周 | 有 1 单成交 | 证明路是通的 |");
add("| 第 2 周 | 淘汰掉 5 个没活的平台 | 减少无效巡检 |");
add("");
add("**关键不是接多少，是验证这套流程走不走得通。**");
add("");
add("## 七、配套文件");
add("");
add("| 文件 | 用途 |");
add("|---|---|");
add("| **接单平台书签-70个.html** | 导入 Chrome，一次把所有平台建好文件夹 |");
add("| 接单平台最终清单-70个.md | 平台详情和分级依据 |");
add("| `_GIG_MASTER.json` | 原始数据 |");
add("");
add("### 怎么导入书签");
add("");
add("1. Chrome → 右上角三点 → 书签 → 书签管理器");
add("2. 右上角三点 → **导入书签**");
add("3. 选 `接单平台书签-70个.html`");
add("4. 书签栏会出现「接单平台 70 个」，里面按类型分好文件夹");
add("");

await fs.writeFile(P2+"\\接单平台每日巡检表.md", rows.join("\n"), "utf8");
const st = await fs.stat(P2+"\\接单平台每日巡检表.md");
return { bytes: st.size, daily: ROUTINE[0].hosts.length, weekly: ROUTINE[1].hosts.length, monthly: ROUTINE[2].hosts.length };
